<?php $titulo_pagina='Vagas';$estilos_pagina=['/assets/css/jobs.css?v=1'];require_once __DIR__.'/includes/functions.php';$q=trim($_GET['q']??'');$cidade=trim($_GET['cidade']??'');$stmt=$mysqli->prepare("SELECT v.*,e.nome_fantasia,e.logo_url FROM vagas v JOIN empresas e ON e.id=v.empresa_id WHERE v.ativa=1 AND (?='' OR v.titulo LIKE CONCAT('%',?,'%') OR v.descricao LIKE CONCAT('%',?,'%')) AND (?='' OR v.cidade LIKE CONCAT('%',?,'%')) ORDER BY v.criado_em DESC");$stmt->bind_param('sssss',$q,$q,$q,$cidade,$cidade);$stmt->execute();$vagas=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/includes/header.php';?><div class="container jobs-page"><h1>Encontre sua próxima oportunidade</h1><form class="job-search"><input name="q" value="<?php echo sanitizar($q); ?>" placeholder="Cargo ou habilidade"><input name="cidade" value="<?php echo sanitizar($cidade); ?>" placeholder="Cidade"><button>Pesquisar vagas</button></form><div class="jobs-grid"><?php foreach($vagas as $vaga): ?><article><small><?php echo sanitizar($vaga['modalidade']); ?></small><h2><?php echo sanitizar($vaga['titulo']); ?></h2><a href="/empresa.php?id=<?php echo (int)$vaga['empresa_id']; ?>"><?php echo sanitizar($vaga['nome_fantasia']); ?></a><p>⌖ <?php echo sanitizar($vaga['cidade'].'/'.$vaga['uf']); ?> · <?php echo sanitizar($vaga['tipo_contrato']); ?></p><strong><?php echo sanitizar($vaga['faixa_salarial']?:'Salário a combinar'); ?></strong><a class="btn" href="/candidatar.php?vaga=<?php echo (int)$vaga['id']; ?>">Ver vaga e candidatar</a></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
